const messagesRoute = route({
    id: "vercel-ai-gateway-messages",
    protocol: AnthropicMessages.protocol,
    api: "messages",
    path: "/messages",
    framing: AnthropicMessages.framing,
    defaults: { headers: { "anthropic-version": "2023-06-01" } },
});
const responsesRoute = route({
    id: "vercel-ai-gateway-responses",
    protocol: OpenResponses.protocol,
    api: "responses",
    path: "/responses",
    framing: Framing.sse,
    defaults: { providerOptions: { store: false, include: ["reasoning.encrypted_content"] } },
});
const chatRoute = route({
    id: "vercel-ai-gateway-chat",
    protocol: OpenAIChat.protocol,
    api: "chat",
    path: "/chat/completions",
    framing: OpenAIChat.framing,
});
export const routes = [messagesRoute, responsesRoute, chatRoute];
const Request = Schema.StructWithRest(Schema.Struct({
    model: Schema.String,
    state: EvaluationInput,
    questions: Schema.Record(Schema.String, EvaluationQuestion),
    providerOptions: Schema.optional(ProviderOptions),
}), [JsonObject]);
const Response = Schema.Struct({
    model: optionalNull(Schema.String),
    answers: Schema.Record(Schema.String, EvaluationAnswer),
    usage: optionalNull(Schema.Struct({
        inputTokens: optionalNull(Schema.Number),
        outputTokens: optionalNull(Schema.Number),
    })),
    rounding: optionalNull(EvaluationRounding),
    providerMetadata: optionalNull(ProviderMetadata),
});
export const configure = (input = {}) => {
    const { apiKey: _apiKey, auth: _auth, baseURL: endpoint, ...defaults } = input;
    const configured = {
        ...defaults,
        endpoint: { baseURL: endpoint ?? baseURL },
        auth: AuthOptions.bearer(input, ["AI_GATEWAY_API_KEY", "VERCEL_OIDC_TOKEN"]),
    };
    const messages = (modelID) => messagesRoute.with(configured).model({
        id: modelID,
        // Recorded Gateway translations for non-Claude models return thinking with empty signatures.
        compatibility: { requireSignature: modelID.startsWith("anthropic/") },
    });
    const responses = (modelID) => responsesRoute.with(configured).model({ id: modelID });
    const chat = (modelID) => chatRoute
        .with(configured)
        .model({ id: modelID, compatibility: { reasoningField: "reasoning" } });
    // Each family uses the API whose Gateway translation carries its reasoning state across turns.
    const model = (modelID) => {
        if (/^(openai\/gpt-|spacexai\/grok-)/.test(modelID))
            return responses(modelID);
        if (modelID.startsWith("meta/muse-"))
            return chat(modelID);
        return messages(modelID);
    };
    const evaluation = (modelID) => EvaluationModel.make({
        id: modelID,
        provider: id,
        http: HttpOptions.make(input.http),
        route: {
            id: "vercel-evaluation",
            evaluate: (req, send) => Effect.gen(function* () {
                const url = new URL(`${(input.baseURL ?? baseURL).replace(/\/$/, "")}/evaluate`);
                Object.entries(req.http?.query ?? {}).forEach(([key, value]) => url.searchParams.set(key, value));
                const body = yield* Schema.encodeUnknownEffect(Schema.fromJsonString(Request))({
                    ...req.http?.body,
                    model: req.model.id,
                    state: req.state,
                    questions: req.questions,
                    providerOptions: req.options,
                }).pipe(Effect.mapError((cause) => new AIError({ reason: new InvalidRequestError({ message: cause.message, cause }) })));
                const headers = yield* Auth.toEffect(configured.auth)({
                    request: req,
                    method: "POST",
                    url: url.toString(),
                    body,
                    headers: Headers.fromInput({ ...input.headers, ...req.http?.headers }),
                });
                const res = yield* send(HttpClientRequest.post(url).pipe(HttpClientRequest.setHeaders(headers), HttpClientRequest.bodyText(body, "application/json")));
                const http = RequestExecutor.responseHttp(res);
                const fail = (message, cause, body) => new AIError({
                    reason: new InvalidProviderOutputError({
                        route: "vercel-evaluation",
                        message,
                        body,
                        http,
                        cause,
                    }),
                });
                const text = yield* res.text.pipe(Effect.mapError((cause) => fail("Failed to read the Vercel AI Gateway evaluation response", cause)));
                const data = yield* Schema.decodeUnknownEffect(Schema.fromJsonString(Response))(text).pipe(Effect.mapError((cause) => fail("Vercel AI Gateway returned an invalid evaluation response", cause, text)));
                const inputTokens = data.usage?.inputTokens ?? undefined;
                const outputTokens = data.usage?.outputTokens ?? undefined;
                const usage = data.usage
                    ? new Usage({
                        inputTokens,
                        outputTokens,
                        totalTokens: ProviderShared.totalTokens(inputTokens, outputTokens, undefined),
                        providerMetadata: { gateway: data.usage },
                    })
                    : undefined;
                return new EvaluationResponse({
                    model: ModelID.make(data.model ?? req.model.id),
                    answers: data.answers,
                    usage,
                    rounding: data.rounding ?? undefined,
                    providerMetadata: data.providerMetadata ?? undefined,
                });
            }),
        },
    });
    return { id, model, messages, responses, chat, experimental: { evaluation }, configure };
};
export const provider = configure();
export const experimental = provider.experimental;
export const messages = provider.messages;
export const responses = provider.responses;
export const chat = provider.chat;
export const model = (modelID, settings) => fromSettings(settings).model(modelID);
export const messagesModel = (modelID, settings) => fromSettings(settings).messages(modelID);
export const responsesModel = (modelID, settings) => fromSettings(settings).responses(modelID);
export const chatModel = (modelID, settings) => fromSettings(settings).chat(modelID);
function fromSettings({ apiKey, baseURL, headers, body, ...providerOptions }) {
    return configure({
        apiKey,
        baseURL,
        headers,
        http: body === undefined ? undefined : { body },
        providerOptions,
    });
}
export * as VercelAIGateway from "./vercel-ai-gateway.js";
